func testFeatureToManyAddOpFeaturePermissions(t *testing.T) {
	var err error

	ctx := context.Background()
	tx := MustTx(boil.BeginTx(ctx, nil))
	defer func() { _ = tx.Rollback() }()

	var a Feature
	var b, c, d, e FeaturePermission

	seed := randomize.NewSeed()
	if err = randomize.Struct(seed, &a, featureDBTypes, false, strmangle.SetComplement(featurePrimaryKeyColumns, featureColumnsWithoutDefault)...); err != nil {
		t.Fatal(err)
	}
	foreigners := []*FeaturePermission{&b, &c, &d, &e}
	for _, x := range foreigners {
		if err = randomize.Struct(seed, x, featurePermissionDBTypes, false, strmangle.SetComplement(featurePermissionPrimaryKeyColumns, featurePermissionColumnsWithoutDefault)...); err != nil {
			t.Fatal(err)
		}
	}

	if err := a.Insert(ctx, tx, boil.Infer()); err != nil {
		t.Fatal(err)
	}
	if err = b.Insert(ctx, tx, boil.Infer()); err != nil {
		t.Fatal(err)
	}
	if err = c.Insert(ctx, tx, boil.Infer()); err != nil {
		t.Fatal(err)
	}

	foreignersSplitByInsertion := [][]*FeaturePermission{
		{&b, &c},
		{&d, &e},
	}

	for i, x := range foreignersSplitByInsertion {
		err = a.AddFeaturePermissions(ctx, tx, i != 0, x...)
		if err != nil {
			t.Fatal(err)
		}

		first := x[0]
		second := x[1]

		if a.ID != first.FeatureID {
			t.Error("foreign key was wrong value", a.ID, first.FeatureID)
		}
		if a.ID != second.FeatureID {
			t.Error("foreign key was wrong value", a.ID, second.FeatureID)
		}

		if first.R.Feature != &a {
			t.Error("relationship was not added properly to the foreign slice")
		}
		if second.R.Feature != &a {
			t.Error("relationship was not added properly to the foreign slice")
		}

		if a.R.FeaturePermissions[i*2] != first {
			t.Error("relationship struct slice not set to correct value")
		}
		if a.R.FeaturePermissions[i*2+1] != second {
			t.Error("relationship struct slice not set to correct value")
		}

		count, err := a.FeaturePermissions().Count(ctx, tx)
		if err != nil {
			t.Fatal(err)
		}
		if want := int64((i + 1) * 2); count != want {
			t.Error("want", want, "got", count)
		}
	}
}

